<template>
  <section class="mci-page-enter">
    <MciPageIntro eyebrow="SERVICE RUNTIME" title="服务目录、实例租约与运行拓扑" description="服务元数据、运行实例、流量策略和调用边都写入共享事实源；实例使用短租约与栅栏令牌跨节点续期和排空。">
      <button type="button" class="mci-button" @click="policyOpen = true">新建流量策略</button>
      <button type="button" class="mci-button" :disabled="!services.length" @click="openInstance()">注册实例</button>
      <button type="button" class="mci-button mci-button--primary" @click="serviceOpen = true">登记服务</button>
    </MciPageIntro>
    <MciStatePanel v-if="state === 'loading'" state="loading" />
    <MciStatePanel v-else-if="state === 'error'" state="error" :message="error" @retry="load" />
    <template v-else>
      <div class="service-metrics"><article v-for="item in serviceMetrics" :key="item.label" class="mci-card"><span :data-tone="item.tone" aria-hidden="true"></span><div><strong>{{ item.value }}</strong><small>{{ item.label }}</small></div></article></div>

      <article class="mci-card mci-section topology-panel">
        <div class="mci-section__head"><div><h2>运行拓扑</h2><p>声明依赖与实际调用边合并，缺失依赖会单独标记。</p></div><span class="mci-badge" :data-tone="topology.MissingDependencies.length ? 'warning' : 'success'">{{ topology.Nodes.length }} 节点 · {{ topology.RuntimeEdges.length }} 调用边</span></div>
        <MciStatePanel v-if="!topology.Nodes.length" state="empty" title="尚无运行拓扑" message="先登记服务，再由调用侧聚合上报运行边。" />
        <template v-else><div class="topology-nodes"><article v-for="node in topology.Nodes" :key="String(node.Id)"><span :data-state="node.HealthState"></span><div><strong>{{ node.Name }}</strong><small>{{ node.Key }} · {{ node.ReadyInstances }} 个就绪实例</small></div></article></div><div class="edge-strip"><span v-for="edge in topology.RuntimeEdges.slice(0, 12)" :key="String(edge.EdgeKey || `${edge.FromServiceId}-${edge.ToServiceId}`)">{{ nodeName(edge.FromServiceId) }} → {{ nodeName(edge.ToServiceId) }} · {{ edge.CallCount || 0 }} 次 · P95 {{ edge.P95DurationMs || 0 }}ms</span><span v-for="edge in topology.MissingDependencies.slice(0, 6)" :key="String(edge.FromServiceId || edge.FromKey) + String(edge.Dependency || edge.ToKey)" class="missing">缺失：{{ edge.FromKey || nodeName(edge.FromServiceId) }} → {{ edge.Dependency || edge.ToKey }}</span></div></template>
      </article>

      <article class="mci-card mci-section service-panel">
        <div class="mci-section__head"><div><h2>服务清单</h2><p>按环境和健康状态定位责任人、端点与依赖。</p></div><div class="filters"><label class="mci-field"><span>环境</span><select v-model="environment"><option value="">全部</option><option>Development</option><option>Test</option><option>Staging</option><option>Production</option></select></label><label class="mci-field"><span>关键词</span><input v-model.trim="keyword" placeholder="服务Key / 名称 / 负责人" /></label></div></div>
        <MciStatePanel v-if="!filtered.length" state="empty" title="没有匹配服务" message="清除筛选或登记第一项服务。" action="登记服务" @action="serviceOpen = true" />
        <div v-else class="service-grid">
          <article v-for="service in filtered" :key="String(service.Id)" class="service-card" tabindex="0">
            <header><span class="service-icon" aria-hidden="true">{{ icon(service.ServiceType) }}</span><div><strong>{{ service.Name }}</strong><small>{{ service.ServiceKey }}</small></div><span class="mci-badge" :data-tone="tone(service.HealthState)">{{ service.HealthState || 'Unknown' }}</span></header>
            <dl><div><dt>类型</dt><dd>{{ service.ServiceType }}</dd></div><div><dt>环境</dt><dd>{{ service.Environment }}</dd></div><div><dt>负责人</dt><dd>{{ service.Owner || '未指定' }}</dd></div><div><dt>就绪实例</dt><dd>{{ readyCount(service.Id) }}</dd></div></dl>
            <details><summary>依赖与端点</summary><code class="mci-code">BaseUrl: {{ service.BaseUrl || '—' }}\nHealthPath: {{ service.HealthPath || '—' }}\nDependencies: {{ service.DependenciesJson || '[]' }}</code></details>
            <footer><button type="button" @click="resolveService(service)">解析实例</button><button type="button" @click="openInstance(service)">注册实例</button></footer>
          </article>
        </div>
        <code v-if="resolveResult" class="mci-code resolve-result">{{ JSON.stringify(resolveResult, null, 2) }}</code>
      </article>

      <div class="mci-grid runtime-grid">
        <article class="mci-card mci-section span-7">
          <div class="mci-section__head"><div><h2>运行实例与租约</h2><p>过期实例不参与解析，排空实例不再接收新流量。</p></div><span class="mci-badge">{{ instances.length }} 个实例</span></div>
          <MciStatePanel v-if="!instances.length" state="empty" title="暂无服务实例" action="注册实例" @action="openInstance()" />
          <MciDataTable v-else :rows="instanceRows" :columns="instanceColumns"><template #actions="{ row }"><button type="button" @click="openInstanceAction(row)">续租 / 排空</button></template></MciDataTable>
        </article>
        <article class="mci-card mci-section span-5">
          <div class="mci-section__head"><div><h2>流量与韧性策略</h2><p>版本权重、重试、熔断、限流和降级统一配置。</p></div><span class="mci-badge">{{ policies.length }} 条</span></div>
          <MciStatePanel v-if="!policies.length" state="empty" title="暂无流量策略" action="新建策略" @action="policyOpen = true" />
          <ol v-else class="policy-list"><li v-for="item in policies.slice(0, 12)" :key="String(item.Id)"><span :data-enabled="item.Enabled"></span><div><strong>{{ item.Name }}</strong><small>{{ serviceName(item.ServiceId) }} · {{ item.VersionNo }} · {{ item.TimeoutMs }}ms</small><code>{{ item.PolicyKey }}</code></div></li></ol>
        </article>
      </div>

      <article v-if="issuedToken" class="one-time-secret" role="status"><div><strong>实例凭据只显示一次</strong><p>立即复制到该实例的可信密钥存储；页面刷新后不会恢复。</p></div><code>{{ issuedToken }}</code><button type="button" @click="copyIssuedToken">复制</button><button type="button" @click="issuedToken = ''">清除</button></article>
      <div v-if="action.message" class="feedback" :data-state="action.status" role="status">{{ action.message }}</div>
    </template>

    <MciDialog :open="serviceOpen" title="登记平台服务" confirm-text="保存服务" :busy="action.status === 'loading'" @cancel="serviceOpen = false" @confirm="createService">
      <div class="form-grid"><label class="mci-field"><span>服务Key</span><input v-model.trim="serviceForm.ServiceKey" placeholder="order-api" /></label><label class="mci-field"><span>服务名称</span><input v-model.trim="serviceForm.Name" placeholder="订单API" /></label><label class="mci-field"><span>类型</span><select v-model="serviceForm.ServiceType"><option>Api</option><option>Worker</option><option>MicroService</option><option>Database</option><option>External</option></select></label><label class="mci-field"><span>环境</span><select v-model="serviceForm.Environment"><option>Development</option><option>Test</option><option>Staging</option><option>Production</option></select></label><label class="mci-field"><span>负责人</span><input v-model.trim="serviceForm.Owner" placeholder="平台团队" /></label><label class="mci-field"><span>基础地址</span><input v-model.trim="serviceForm.BaseUrl" placeholder="https://api.example.com" /></label><label class="mci-field"><span>健康路径</span><input v-model.trim="serviceForm.HealthPath" placeholder="/health/ready" /></label><label class="mci-field full"><span>依赖 JSON</span><textarea v-model="serviceForm.DependenciesJson" spellcheck="false"></textarea></label></div>
      <p>这里只登记服务元数据；不会主动探测或修改该服务。</p>
    </MciDialog>
    <MciDialog :open="instanceOpen" title="注册服务运行实例" confirm-text="注册并领取租约" :busy="action.status === 'loading'" @cancel="instanceOpen = false" @confirm="registerInstance">
      <div class="form-grid"><label class="mci-field"><span>服务</span><select v-model="instanceForm.ServiceKey"><option v-for="item in services" :key="String(item.Id)" :value="item.ServiceKey">{{ item.Name }} · {{ item.ServiceKey }}</option></select></label><label class="mci-field"><span>实例Key</span><input v-model.trim="instanceForm.InstanceKey" placeholder="order-api:node-01" /></label><label class="mci-field full"><span>实例端点</span><input v-model.trim="instanceForm.Endpoint" placeholder="http://10.0.0.12:8080" /></label><label class="mci-field"><span>版本</span><input v-model.trim="instanceForm.VersionNo" placeholder="7.2.5" /></label><label class="mci-field"><span>可用区</span><input v-model.trim="instanceForm.Zone" placeholder="cn-east-1a" /></label><label class="mci-field"><span>权重</span><input v-model.number="instanceForm.Weight" type="number" min="0" max="1000" /></label><label class="mci-field"><span>租约秒数</span><input v-model.number="instanceForm.LeaseSeconds" type="number" min="15" max="300" /></label><label class="mci-field full"><span>标签 JSON</span><textarea v-model="instanceForm.LabelsJson" spellcheck="false"></textarea></label></div>
    </MciDialog>
    <MciDialog :open="instanceActionOpen" title="实例租约与流量状态" confirm-text="执行操作" :busy="action.status === 'loading'" @cancel="closeInstanceAction" @confirm="runInstanceAction">
      <div class="form-grid"><label class="mci-field"><span>操作</span><select v-model="instanceAction.Operation"><option value="Heartbeat">心跳续租</option><option value="Drain">开始排空</option><option value="Undrain">恢复接流</option><option value="Unavailable">标记不可用</option></select></label><label class="mci-field"><span>租约秒数</span><input v-model.number="instanceAction.LeaseSeconds" type="number" min="15" max="300" /></label><label class="mci-field full"><span>实例凭据</span><input v-model="instanceAction.InstanceToken" type="password" autocomplete="off" /></label></div><code class="mci-code">{{ serviceName(instanceActionTarget?.ServiceId) }} / {{ instanceActionTarget?.InstanceKey }}\nFencingToken: {{ instanceActionTarget?.FencingToken }}</code>
    </MciDialog>
    <MciDialog :open="policyOpen" title="发布流量与韧性策略" confirm-text="校验并发布" :busy="action.status === 'loading'" @cancel="policyOpen = false" @confirm="createPolicy">
      <div class="form-grid"><label class="mci-field"><span>策略Key</span><input v-model.trim="policyForm.PolicyKey" placeholder="order-api-stable" /></label><label class="mci-field"><span>策略名称</span><input v-model.trim="policyForm.Name" /></label><label class="mci-field"><span>服务</span><select v-model="policyForm.ServiceId"><option v-for="item in services" :key="String(item.Id)" :value="String(item.Id)">{{ item.Name }}</option></select></label><label class="mci-field"><span>策略版本</span><input v-model.trim="policyForm.VersionNo" placeholder="1.0.0" /></label><label class="mci-field"><span>超时毫秒</span><input v-model.number="policyForm.TimeoutMs" type="number" min="50" max="600000" /></label><label class="mci-field"><span>负责人</span><input v-model.trim="policyForm.Owner" /></label><label class="mci-field full"><span>主体匹配 JSON</span><textarea v-model="policyForm.MatchJson" spellcheck="false"></textarea></label><label class="mci-field full"><span>版本 / 机房 / 标签权重 JSON</span><textarea v-model="policyForm.TargetsJson" spellcheck="false"></textarea></label><label class="mci-field full"><span>重试 / 熔断 / 限流 / 降级 JSON</span><textarea v-model="policyForm.ResilienceJson" spellcheck="false"></textarea></label></div>
      <div class="policy-actions"><button type="button" class="mci-button" :disabled="action.status === 'loading'" @click="previewPolicy">DryRun 校验</button><small>发布使用稳定摘要、版本证据和乐观并发；不会静默覆盖他人修改。</small></div><code v-if="policyPreview" class="mci-code policy-preview">{{ JSON.stringify(policyPreview, null, 2) }}</code>
    </MciDialog>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import MciDataTable from '../components/MciDataTable.vue'
import MciDialog from '../components/MciDialog.vue'
import MciPageIntro from '../components/MciPageIntro.vue'
import MciStatePanel from '../components/MciStatePanel.vue'
import type { ActionState, HostContext } from '../domain/models'
import { addRow, getTable, runEngine } from '../platform/client'

const props = defineProps<{ context: HostContext }>()
type Row = Record<string, any>
interface Topology { Nodes: Row[]; RuntimeEdges: Row[]; DeclaredEdges: Row[]; MissingDependencies: Row[]; GeneratedAt: string }
const emptyTopology = (): Topology => ({ Nodes: [], RuntimeEdges: [], DeclaredEdges: [], MissingDependencies: [], GeneratedAt: '' })
const services = ref<Row[]>([]), instances = ref<Row[]>([]), policies = ref<Row[]>([]), topology = ref<Topology>(emptyTopology())
const state = ref<'loading' | 'ready' | 'error'>('loading'), error = ref(''), keyword = ref(''), environment = ref('')
const serviceOpen = ref(false), instanceOpen = ref(false), instanceActionOpen = ref(false), policyOpen = ref(false), action = reactive<ActionState>({ status: 'idle' })
const resolveResult = ref<unknown>(null), policyPreview = ref<unknown>(null), issuedToken = ref(''), instanceActionTarget = ref<Row | null>(null)
const serviceForm = reactive({ ServiceKey: '', Name: '', ServiceType: 'Api', Environment: 'Test', Owner: '', BaseUrl: '', HealthPath: '/health/ready', DependenciesJson: '[]' })
const instanceForm = reactive({ ServiceKey: '', InstanceKey: '', Endpoint: '', VersionNo: '', Zone: '', Weight: 100, LeaseSeconds: 60, LabelsJson: '{}' })
const instanceAction = reactive({ Operation: 'Heartbeat', InstanceToken: '', LeaseSeconds: 60 })
const policyForm = reactive({ PolicyKey: '', Name: '', ServiceId: '', VersionNo: '1.0.0', TimeoutMs: 10000, Owner: '', MatchJson: '{\n  "AllowedRoleIds": [],\n  "DeniedRoleIds": [],\n  "SubjectKeys": [],\n  "Percentage": 100,\n  "Priority": 0\n}', TargetsJson: '[\n  {"VersionNo": "*", "Zone": "", "Labels": {}, "Weight": 100, "Enabled": 1}\n]', ResilienceJson: '{\n  "retry": {"MaxAttempts": 3, "BaseDelayMs": 200, "RetryStatusCodes": [408, 429, 500, 502, 503, 504]},\n  "circuit": {"FailureThreshold": 5, "BreakSeconds": 30, "HalfOpenMaxCalls": 1},\n  "rateLimit": {"Requests": 0, "WindowSeconds": 60, "Scope": "Subject"},\n  "degrade": {"Mode": "Fail", "ServiceKey": "", "StaticResponse": null}\n}' })
const filtered = computed(() => services.value.filter((item) => (!environment.value || item.Environment === environment.value) && (!keyword.value || [item.ServiceKey, item.Name, item.Owner].join(' ').toLowerCase().includes(keyword.value.toLowerCase()))))
const serviceMetrics = computed(() => [
  { label: '目录服务', value: services.value.length, tone: 'primary' },
  { label: '就绪实例', value: instances.value.filter((x) => x.State === 'Ready' && (!x.LeaseExpiresAt || x.LeaseExpiresAt > nowText())).length, tone: 'success' },
  { label: '排空 / 降级', value: instances.value.filter((x) => x.State === 'Draining').length + services.value.filter((x) => x.HealthState === 'Degraded').length, tone: 'warning' },
  { label: '失效 / 未知', value: instances.value.filter((x) => ['Unavailable', 'Expired'].includes(x.State)).length + services.value.filter((x) => ['Down', 'Unknown', '', null].includes(x.HealthState)).length, tone: 'danger' }
])
const instanceRows = computed(() => instances.value.map((item) => ({ ...item, ServiceName: serviceName(item.ServiceId) })))
const instanceColumns = [{ key: 'ServiceName', label: '服务' }, { key: 'InstanceKey', label: '实例Key' }, { key: 'VersionNo', label: '版本' }, { key: 'Zone', label: '可用区' }, { key: 'State', label: '状态', tone: true }, { key: 'LeaseExpiresAt', label: '租约到期' }, { key: 'FencingToken', label: '栅栏令牌' }]
function nowText() { return new Date().toISOString().replace('T', ' ').slice(0, 19) }
function icon(type: string) { return ({ Api: '↔', Worker: '⚙', MicroService: '▦', Database: '▤', External: '◎' } as Record<string,string>)[type] || '◇' }
function tone(value: string) { return value === 'Healthy' ? 'success' : value === 'Degraded' ? 'warning' : 'danger' }
function serviceName(id: unknown) { return services.value.find((item) => String(item.Id) === String(id))?.Name || String(id || '未知服务') }
function nodeName(id: unknown) { return topology.value.Nodes.find((item) => String(item.Id) === String(id))?.Name || serviceName(id) }
function readyCount(id: unknown) { return instances.value.filter((item) => String(item.ServiceId) === String(id) && item.State === 'Ready' && (!item.LeaseExpiresAt || item.LeaseExpiresAt > nowText())).length }
function parseJson(value: string, label: string) { try { return JSON.parse(value || '{}') } catch { throw new Error(`${label}必须是有效 JSON。`) } }
async function load() { state.value = 'loading'; error.value = ''; try { const [s, i, p, t] = await Promise.all([getTable<Row>(props.context, 'mci_service_registry', { _OrderBy: 'Name', _OrderByType: 'ASC' }), getTable<Row>(props.context, 'mci_service_instance', { _OrderBy: 'LastHeartbeatTime', _OrderByType: 'DESC' }), getTable<Row>(props.context, 'mci_service_route_policy'), runEngine<Topology>(props.context, 'mci-service-topology').catch(() => emptyTopology())]); services.value = s.rows; instances.value = i.rows; policies.value = p.rows; topology.value = t; instanceForm.ServiceKey ||= String(services.value[0]?.ServiceKey || ''); policyForm.ServiceId ||= String(services.value[0]?.Id || ''); state.value = 'ready' } catch (e) { error.value = e instanceof Error ? e.message : '加载失败'; state.value = 'error' } }
async function act<T>(work: () => Promise<T>, success: string) { action.status = 'loading'; action.message = ''; try { const result = await work(); action.status = 'success'; action.message = success; return result } catch (e) { action.status = 'error'; action.message = e instanceof Error ? e.message : '执行失败'; return null } }
async function createService() { if (!serviceForm.ServiceKey || !serviceForm.Name) { action.status = 'error'; action.message = '服务Key和名称不能为空。'; return } let dependencies: unknown; try { dependencies = parseJson(serviceForm.DependenciesJson, '依赖') } catch (e) { action.status = 'error'; action.message = (e as Error).message; return } const result = await act(() => addRow(props.context, 'mci_service_registry', { ...serviceForm, DependenciesJson: JSON.stringify(dependencies), HealthState: 'Unknown', Enabled: 1 }), '服务已登记。'); if (result) { serviceOpen.value = false; await load() } }
function openInstance(service?: Row) { if (service) instanceForm.ServiceKey = service.ServiceKey; else instanceForm.ServiceKey ||= String(services.value[0]?.ServiceKey || ''); instanceOpen.value = true }
async function registerInstance() { if (!instanceForm.ServiceKey || !instanceForm.InstanceKey || !instanceForm.Endpoint) { action.status = 'error'; action.message = '服务、实例Key和端点不能为空。'; return } let labels: unknown; try { labels = parseJson(instanceForm.LabelsJson, '标签') } catch (e) { action.status = 'error'; action.message = (e as Error).message; return } const result = await act(() => runEngine<Row>(props.context, 'mci-service-instance-register', { ...instanceForm, Labels: labels }), '服务实例已注册。'); if (result) { if (result.InstanceToken) issuedToken.value = String(result.InstanceToken); instanceOpen.value = false; await load() } }
function openInstanceAction(row: Row) { instanceActionTarget.value = row; instanceAction.Operation = row.State === 'Draining' ? 'Undrain' : 'Heartbeat'; instanceAction.InstanceToken = ''; instanceAction.LeaseSeconds = Number(row.LeaseSeconds || 60); instanceActionOpen.value = true }
function closeInstanceAction() { instanceActionOpen.value = false; instanceAction.InstanceToken = '' }
async function runInstanceAction() { const row = instanceActionTarget.value; if (!row || !instanceAction.InstanceToken) { action.status = 'error'; action.message = '实例凭据不能为空。'; return } const service = services.value.find((item) => String(item.Id) === String(row.ServiceId)); const heartbeat = instanceAction.Operation === 'Heartbeat'; const result = await act(() => runEngine(props.context, heartbeat ? 'mci-service-instance-heartbeat' : 'mci-service-instance-drain', heartbeat ? { ServiceKey: service?.ServiceKey, InstanceKey: row.InstanceKey, InstanceToken: instanceAction.InstanceToken, LeaseSeconds: instanceAction.LeaseSeconds, State: row.State === 'Draining' ? 'Draining' : 'Ready' } : { InstanceId: row.Id, InstanceToken: instanceAction.InstanceToken, Action: instanceAction.Operation }), heartbeat ? '实例租约已续期。' : '实例流量状态已更新。'); if (result) { closeInstanceAction(); await load() } }
async function resolveService(service: Row) { const result = await act(() => runEngine(props.context, 'mci-service-resolve', { ServiceKey: service.ServiceKey, SubjectKey: 'studio-preview' }), '服务实例解析完成。'); if (result) resolveResult.value = result }
function policyPayload(dryRun: boolean) { const match = parseJson(policyForm.MatchJson, '主体匹配'); const targets = parseJson(policyForm.TargetsJson, '版本与流量目标'); const resilient = parseJson(policyForm.ResilienceJson, '韧性策略') as Row; return { PolicyKey: policyForm.PolicyKey, Name: policyForm.Name, ServiceId: policyForm.ServiceId, VersionNo: policyForm.VersionNo, TimeoutMs: policyForm.TimeoutMs, Owner: policyForm.Owner, Match: match, Targets: targets, Retry: resilient.retry || {}, Circuit: resilient.circuit || {}, RateLimit: resilient.rateLimit || {}, Degrade: resilient.degrade || {}, ExpectedContentHash: '', ChangeSummary: 'AI平台治理中心发布服务流量与韧性策略', Enabled: 1, DryRun: dryRun } }
async function previewPolicy() { if (!policyForm.PolicyKey || !policyForm.Name || !policyForm.ServiceId) { action.status = 'error'; action.message = '策略Key、名称和服务不能为空。'; return } let payload: Row; try { payload = policyPayload(true) } catch (e) { action.status = 'error'; action.message = (e as Error).message; return } const result = await act(() => runEngine<Row>(props.context, 'mci-service-policy-publish', payload), '策略协议校验通过，尚未发布。'); if (result) policyPreview.value = result }
async function createPolicy() { if (!policyForm.PolicyKey || !policyForm.Name || !policyForm.ServiceId) { action.status = 'error'; action.message = '策略Key、名称和服务不能为空。'; return } let payload: Row; try { payload = policyPayload(false) } catch (e) { action.status = 'error'; action.message = (e as Error).message; return } const result = await act(() => runEngine<Row>(props.context, 'mci-service-policy-publish', payload), '流量与韧性策略已发布。'); if (result) { policyPreview.value = null; policyOpen.value = false; await load() } }
async function copyIssuedToken() { try { await navigator.clipboard.writeText(issuedToken.value); action.status = 'success'; action.message = '实例凭据已复制。' } catch { action.status = 'error'; action.message = '浏览器未允许复制，请手工选取。' } }
onMounted(load)
</script>

